%[text] ## Physical Problem: Membrane Deflection BVP
%[text] A string under distributed load satisfies: $ \\frac{d^2 u}{dx^2} +  \\frac{d^2 u}{dy^2}= 1 $ on $ \[0,1\] $ with $ u(0) = 0 $ and $ u(1) = 0 $ (fixed ends). Here $ u(x) $ is deflection and we have a constant unit load $ f(x) = 1 $.
N = 20;
M = 20;
x = linspace(0,2,N);
y = linspace(0,1,M);
dx = x(2)-x(1) %[output:63742505]
dy = y(2)-y(1) %[output:03c2df42]

Map = zeros(N,M);
Counter = 1;
figure(Position=[0,0,800,600]) %[output:29b831a1]
for ix = 1:N
    for iy = 1:M
        Map(ix,iy) = Counter;
        scatter(x(ix),y(iy),200,SeriesIndex=1) %[output:29b831a1]
        hold on
        text(x(ix),y(iy),string(Map(ix,iy)),VerticalAlignment="middle",HorizontalAlignment="center")
        Counter = Counter + 1;
    end
end
axis off %[output:29b831a1]
axis equal %[output:29b831a1]
%%
A = zeros(N*M);
b = zeros(N*M,1);

for ix = 2:N-1
    for iy = 2:M-1
        EqnId = Map(ix,iy);

        A(EqnId, EqnId) = -2/dx^2 -2/dy^2;
        A(EqnId, Map(ix-1,iy)) = 1/dx^2;
        A(EqnId, Map(ix+1,iy)) = 1/dx^2;
        A(EqnId, Map(ix,iy-1)) = 1/dy^2;
        A(EqnId, Map(ix,iy+1)) = 1/dy^2;

        b(EqnId) = 1;
    end
end

% Boundary condition
% Bottom
for ix = 1:N
    EqnId = Map(ix,1);
    A(EqnId,EqnId) = 1;
    b(EqnId) = 0;
end

% Top
for ix = 1:N
    EqnId = Map(ix,M);
    A(EqnId,EqnId) = 1;
    b(EqnId) = 0;
end

% Left
for iy = 1:M
    EqnId = Map(1,iy);
    A(EqnId,EqnId) = 1;
    b(EqnId) = 0;
end

for iy = 1:M
    EqnId = Map(N,iy);
    A(EqnId,EqnId) = 1;
    b(EqnId) = 0;
end

u = A\b;
[X,Y] = meshgrid(x,y);
u = reshape(u,size(X));
figure %[output:50649f5d]
contourf(X,Y,u,10,LineStyle="-") %[output:50649f5d]

